// Methods generated by foreign! are typed by the declaration.
fil_rust::foreign! {
    struct Math {
        fn abs(x: i32) -> i32;
    }
}

fn main() {
    let rt = fil_rust::Runtime::get().unwrap();
    rt.run(|fil| {
        let math = Math::from_library(fil, fil.libc().clone()).unwrap();
        let _ = math.abs(fil, 1.5f64);
    });
}
